#include <stdlib.h>

typedef struct {
    int* parent;
    int* size;
    int* infectedCount;
    int n;
} UnionFind;

UnionFind* ufCreate(int n) {
    UnionFind* uf = (UnionFind*)malloc(sizeof(UnionFind));
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->size = (int*)malloc(n * sizeof(int));
    uf->infectedCount = (int*)calloc(n, sizeof(int));
    uf->n = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->size[i] = 1;
    }
    return uf;
}

int ufFind(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = ufFind(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void ufUnion(UnionFind* uf, int x, int y) {
    int rx = ufFind(uf, x);
    int ry = ufFind(uf, y);
    if (rx != ry) {
        if (uf->size[rx] < uf->size[ry]) {
            int tmp = rx; rx = ry; ry = tmp;
        }
        uf->parent[ry] = rx;
        uf->size[rx] += uf->size[ry];
        uf->infectedCount[rx] += uf->infectedCount[ry];
    }
}

void ufFree(UnionFind* uf) {
    free(uf->parent);
    free(uf->size);
    free(uf->infectedCount);
    free(uf);
}

int cmpInt(const void* a, const void* b) {
    int x = *(int*)a;
    int y = *(int*)b;
    return x - y;
}

int minMalwareSpread(int** graph, int graphSize, int* graphColSize, int* initial, int initialSize){
    int n = graphSize;
    // Sort initial to ensure smallest index if tie
    qsort(initial, initialSize, sizeof(int), cmpInt);

    UnionFind* uf = ufCreate(n);

    // Union all connected nodes
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            if (graph[i][j] == 1) {
                ufUnion(uf, i, j);
            }
        }
    }

    // Count infected nodes in each component
    for (int i = 0; i < initialSize; i++) {
        int root = ufFind(uf, initial[i]);
        uf->infectedCount[root]++;
    }

    int ans = initial[0];
    int maxSaved = -1;

    // For each node in initial, check if removing it saves nodes
    for (int i = 0; i < initialSize; i++) {
        int node = initial[i];
        int root = ufFind(uf, node);
        // If this component has exactly one infected node (this node),
        // removing it will save the entire component size
        if (uf->infectedCount[root] == 1) {
            if (uf->size[root] > maxSaved) {
                maxSaved = uf->size[root];
                ans = node;
            }
        }
    }

    // If no node saves any, return smallest index node
    ufFree(uf);
    return ans;
}

